(() => {
    "use strict";

    // ----------- 4-RINGS OR 4-SQUARES PUZZLE -----------

    // rings :: noRepeatedDigits -> DigitList -> solutions
    // rings :: Bool -> [Int] -> [[Int]]
    const rings = uniq =>
        digits => Boolean(digits.length) ? (
            () => {
                const ns = digits.sort(flip(compare));

                // CENTRAL DIGIT :: d
                return ns.flatMap(
                    ringTriage(uniq)(ns)
                );
            })() : [];


    const ringTriage = uniq => ns => d => {
        const
            h = head(ns),
            ts = ns.filter(x => (x + d) <= h);

        // LEFT OF CENTRE :: c and a
        return (
            uniq ? (delete_(d)(ts)) : ns
        )
        .flatMap(c => {
            const a = c + d;

            // RIGHT OF CENTRE :: e and g
            return a > h ? (
                []
            ) : (
                uniq ? (
                    difference(ts)([d, c, a])
                ) : ns
            )
            .flatMap(subTriage(uniq)([ns, h, a, c, d]));
        });
    };


    const subTriage = uniq =>
        ([ns, h, a, c, d]) => e => {
            const g = d + e;

            return ((g > h) || (
                uniq && (g === c))
            ) ? (
                    []
                ) : (() => {
                    const
                        agDelta = a - g,
                        bfs = uniq ? (
                            difference(ns)([
                                d, c, e, g, a
                            ])
                        ) : ns;

                    // MID LEFT, MID RIGHT :: b and f
                    return bfs.flatMap(b => {
                        const f = b + agDelta;

                        return (bfs).includes(f) && (
                            !uniq || ![
                                a, b, c, d, e, g
                            ].includes(f)
                        ) ? ([
                                [a, b, c, d, e, f, g]
                            ]) : [];
                    });
                })();
        };

    // ---------------------- TEST -----------------------
    const main = () => unlines([
        "rings(true, enumFromTo(1,7))\n",
        unlines(
            rings(true)(
                enumFromTo(1)(7)
            ).map(show)
        ),

        "\nrings(true, enumFromTo(3, 9))\n",
        unlines(
            rings(true)(
                enumFromTo(3)(9)
            ).map(show)
        ),

        "\nlength(rings(false, enumFromTo(0, 9)))\n",
        rings(false)(
            enumFromTo(0)(9)
        )
        .length
        .toString(),
        ""
    ]);


    // ---------------- GENERIC FUNCTIONS ----------------

    // compare :: a -> a -> Ordering
    const compare = (a, b) =>
        a < b ? -1 : (a > b ? 1 : 0);


    // delete :: Eq a => a -> [a] -> [a]
    const delete_ = x => {
        // xs with first instance of x (if any) removed.
        const go = xs =>
            Boolean(xs.length) ? (
                (x === xs[0]) ? (
                    xs.slice(1)
                ) : [xs[0]].concat(go(xs.slice(1)))
            ) : [];

        return go;
    };


    // difference :: Eq a => [a] -> [a] -> [a]
    const difference = xs =>
        ys => {
            const s = new Set(ys);

            return xs.filter(x => !s.has(x));
        };


    // enumFromTo :: Int -> Int -> [Int]
    const enumFromTo = m =>
        n => Array.from({
            length: 1 + n - m
        }, (_, i) => m + i);


    // flip :: (a -> b -> c) -> b -> a -> c
    const flip = op =>
        // The binary function op with
        // its arguments reversed.
        1 !== op.length ? (
            (a, b) => op(b, a)
        ) : (a => b => op(b)(a));


    // head :: [a] -> a
    const head = xs =>
        // The first item (if any) in a list.
        Boolean(xs.length) ? (
            xs[0]
        ) : null;


    // show :: a -> String
    const show = x =>
        JSON.stringify(x);


    // unlines :: [String] -> String
    const unlines = xs =>
        // A single string formed by the intercalation
        // of a list of strings with the newline character.
        xs.join("\n");


    // MAIN ---
    return main();
})();

var sec_old = 0;
function update_clock() {
	var t = new Date();
	var arms = [t.getHours(), t.getMinutes(), t.getSeconds()];
	if (arms[2] == sec_old) return;
	sec_old = arms[2];

	var c = document.getElementById('clock');
	var ctx = c.getContext('2d');
	ctx.fillStyle = "rgb(0,200,200)";
	ctx.fillRect(0, 0, c.width, c.height);
	ctx.fillStyle = "white";
	ctx.fillRect(3, 3, c.width - 6, c.height - 6);
	ctx.lineCap = 'round';

	var orig = { x: c.width / 2, y: c.height / 2 };
	arms[1] += arms[2] / 60;
	arms[0] += arms[1] / 60;
	draw_arm(ctx, orig, arms[0] * 30, c.width/2.5 - 15, c.width / 20,  "green");
	draw_arm(ctx, orig, arms[1] * 6,  c.width/2.2 - 10, c.width / 30,  "navy");
	draw_arm(ctx, orig, arms[2] * 6,  c.width/2.0 - 6,  c.width / 100, "maroon");
}

function draw_arm(ctx, orig, deg, len, w, style)
{
	ctx.save();
	ctx.lineWidth = w;
	ctx.lineCap = 'round';
	ctx.translate(orig.x, orig.y);
	ctx.rotate((deg - 90) * Math.PI / 180);
	ctx.strokeStyle = style;
	ctx.beginPath();
	ctx.moveTo(-len / 10, 0);
	ctx.lineTo(len, 0);
	ctx.stroke();
	ctx.restore();
}

function init_clock() {
	var clock = document.createElement('canvas');
	clock.width = 100;
	clock.height = 100;
	clock.id = "clock";
	document.body.appendChild(clock);

	window.setInterval(update_clock, 200);
}

