') col = 0;
		if (!s[i]) break;
	}

	for (s = in, i = col = 0; s[i]; s += i + 1) {
		for (i = 0; s[i] && s[i] != '$' && s[i] != '
'; i++);

		switch(alignment) {
		case 'l':	r = w[col] - i; break;
		case 'c':	r = (w[col] - i)/2; break;
